edits.oldText:
// 2. Player / 4-Player Raid Squad on Left Side
if (bs.mode === "raid" && bs.raidSquad.length > 0) {
  // 2x2 staggered formation from footage C 07:28
  const coords = [
    { x: 310, y: GROUND_Y - 35 },
    { x: 205, y: GROUND_Y - 35 },
    { x: 280, y: GROUND_Y + 8 },
    { x: 170, y: GROUND_Y + 8 },
  ];
  bs.raidSquad.forEach((unit, idx) => {
    const pos = coords[idx] || coords[0];
    Sprites.drawOverCharacter(ctx, pos.x, pos.y, {
      armor: unit.armor,
      animTime: animTime + idx * 0.4,
      running: false,
      jumping: false,
      chargeTier: getCShotLevel(bs) >= 1 ? 2 : 0,
      shooting: bs.playerShooting,
      hurt: idx === 0 ? bs.playerHurt : 0,
      label: unit.name,
    });
  });
} else {
  Sprites.drawOverCharacter(ctx, 270, GROUND_Y, {
    armor: game.getEquippedArmor(),
    animTime,
    running: false,
    jumping: false,
    chargeTier: getCShotLevel(bs) >= 2 ? 3 : getCShotLevel(bs) >= 1 ? 2 : 0,
    shooting: bs.playerShooting,
    hurt: bs.playerHurt,
    label: game.playerName,
  });
}

// Active Buff Icons above Player (Rule 13: ATK↑, DEF↑)
let buffX = 225;
if (bs.buffs.atkUp > 0) {
  ctx.fillStyle = "#dc2626";
  ctx.fillRect(buffX, GROUND_Y - 88, 38, 18);
  ctx.fillStyle = "#ffffff";
  ctx.font = "bold 10px monospace";
  ctx.textAlign = "center";
  ctx.fillText("ATK↑", buffX + 19, GROUND_Y - 75);
  buffX += 42;
}
if (bs.buffs.defUp > 0) {
  ctx.fillStyle = "#2563eb";
  ctx.fillRect(buffX, GROUND_Y - 88, 38, 18);
  ctx.fillStyle = "#ffffff";
  ctx.font = "bold 10px monospace";
  ctx.textAlign = "center";
  ctx.fillText("DEF↑", buffX + 19, GROUND_Y - 75);
}

// 3. Boss or Rival OVER Unit on Right Side
if (bs.mode === "arena") {
  const rivalArmor = GameData.ARMORS.find((a) => a.id === bs.boss.armorId) || GameData.ARMORS[1];
  Sprites.drawOverCharacter(ctx, 960, GROUND_Y, {
    armor: rivalArmor,
    animTime,
    running: false,
    jumping: false,
    facing: -1,
    scale: 1.15,
    hurt: bs.bossHurt,
    label: bs.boss.name,
  });
} else {
  Sprites.drawBoss(ctx, 955, GROUND_Y, bs.boss, animTime, bs.bossHurt);
}

edits.newText:
// 2. Player / 4-Player Raid Squad on Left Side (with dash-to-center lunge on attack per Footage A 10:21-10:45)
let playerLungeX = 0;
let playerDashing = false;
if (bs.turnPhase === "player_attack") {
  const dur = bs.mode === "raid" ? 0.95 : 0.65;
  const prog = Math.max(0, Math.min(1, 1 - bs.phaseTimer / dur));
  playerLungeX = Math.sin(prog * Math.PI) * 260;
  playerDashing = true;
}

if (bs.mode === "raid" && bs.raidSquad.length > 0) {
  // 2x2 staggered formation from footage C 07:28
  const coords = [
    { x: 310, y: GROUND_Y - 35 },
    { x: 205, y: GROUND_Y - 35 },
    { x: 280, y: GROUND_Y + 8 },
    { x: 170, y: GROUND_Y + 8 },
  ];
  bs.raidSquad.forEach((unit, idx) => {
    const pos = coords[idx] || coords[0];
    Sprites.drawOverCharacter(ctx, pos.x + playerLungeX * (idx === 0 ? 1 : 0.65), pos.y, {
      armor: unit.armor,
      animTime: animTime + idx * 0.4,
      running: playerDashing,
      jumping: false,
      chargeTier: getCShotLevel(bs) >= 1 ? 2 : 0,
      shooting: bs.playerShooting,
      hurt: idx === 0 ? bs.playerHurt : 0,
      label: unit.name,
    });
  });
} else {
  Sprites.drawOverCharacter(ctx, 270 + playerLungeX, GROUND_Y, {
    armor: game.getEquippedArmor(),
    animTime,
    running: playerDashing,
    jumping: false,
    chargeTier: getCShotLevel(bs) >= 2 ? 3 : getCShotLevel(bs) >= 1 ? 2 : 0,
    shooting: bs.playerShooting,
    hurt: bs.playerHurt,
    label: game.playerName,
  });
}

// Active Buff Icons above Player (Rule 13: ATK↑, DEF↑)
let buffX = 225 + playerLungeX;
if (bs.buffs.atkUp > 0) {
  ctx.fillStyle = "#dc2626";
  ctx.fillRect(buffX, GROUND_Y - 88, 38, 18);
  ctx.fillStyle = "#ffffff";
  ctx.font = "bold 10px monospace";
  ctx.textAlign = "center";
  ctx.fillText("ATK↑", buffX + 19, GROUND_Y - 75);
  buffX += 42;
}
if (bs.buffs.defUp > 0) {
  ctx.fillStyle = "#2563eb";
  ctx.fillRect(buffX, GROUND_Y - 88, 38, 18);
  ctx.fillStyle = "#ffffff";
  ctx.font = "bold 10px monospace";
  ctx.textAlign = "center";
  ctx.fillText("DEF↑", buffX + 19, GROUND_Y - 75);
}

// 3. Boss or Rival OVER Unit on Right Side (with tackle lunge across arena during boss_turn per Footage A 10:25-10:40)
let bossLungeX = 0;
let bossLungeY = 0;
if (bs.turnPhase === "boss_turn" && bs.buffs.stop <= 0) {
  const prog = Math.max(0, Math.min(1, 1 - bs.phaseTimer / 0.7));
  bossLungeX = -Math.sin(prog * Math.PI) * 580;
  bossLungeY = -Math.sin(prog * Math.PI) * 28;
}

if (bs.mode === "arena") {
  const rivalArmor = GameData.ARMORS.find((a) => a.id === bs.boss.armorId) || GameData.ARMORS[1];
  Sprites.drawOverCharacter(ctx, 960 + bossLungeX, GROUND_Y + bossLungeY, {
    armor: rivalArmor,
    animTime,
    running: bossLungeX < -10,
    jumping: bossLungeY < -8,
    facing: -1,
    scale: 1.15,
    hurt: bs.bossHurt,
    label: bs.boss.name,
  });
} else {
  Sprites.drawBoss(ctx, 955 + bossLungeX, GROUND_Y + bossLungeY, bs.boss, animTime, bs.bossHurt);
}
